    ['esfera', 6.6, 3.5,-4.5,.95,'#C9B8FF'],
    ['esfera',-6.7,-1.5,-3.6,.55,'#D4F75A'],
    ['esfera', 4.2,-3.4,-2.6,.32,'#B55D49'],
