/* ===== empilhamento: cada seção pina quando seu fim chega ===== */
(function(){
  var secs=[].slice.call(document.querySelectorAll('.sec'));
  secs.forEach(function(s){
    var palco=document.createElement('div'); palco.className='palco';
    s.parentNode.insertBefore(palco,s); palco.appendChild(s);
  });
  function medir(){
    var vh=window.innerHeight;
    secs.forEach(function(s){
      var h=s.offsetHeight;
      s.style.top = Math.min(0, vh - h) + 'px';
      /* respiro: a seção fica parada um tempo antes da próxima subir por cima */
      var folga = s.dataset.trava ? vh*parseFloat(s.dataset.trava) : (s.classList.contains('foto') ? vh*0.22 : vh*0.40);
      s.parentNode.style.height = Math.round(h + folga) + 'px';
      if(s.id==='servicos' || s.hasAttribute('data-lado') || s.hasAttribute('data-sobe')) s.parentNode.style.marginTop = (-vh) + 'px';
    });
  }
  medir();
  addEventListener('resize',medir); addEventListener('load',medir);
  if('ResizeObserver' in window){var ro=new ResizeObserver(medir); secs.forEach(function(s){ro.observe(s)})}
})();

/* ===== topo: some ao descer, lê a cor da seção embaixo, menu mobile ===== */
(function(){
  var t=document.getElementById('topo'); if(!t) return;
  var hamb=t.querySelector('.hamb'), lona=document.getElementById('lona');
  var CLARO={'off':1,'lilas':1,'lima':1};
  var ultimo=0, aberta=false;
  var CORTE=0.2;   /* luminância em que o contraste de branco e de azul-profundo se igualam */

  function lum(r,g,b){ var f=function(v){ v/=255; return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4) }; return .2126*f(r)+.7152*f(g)+.0722*f(b) }
  function lerCor(c){ var m=c.match(/rgba?\(([^)]+)\)/); if(!m) return null; var p=m[1].split(',').map(parseFloat); return {r:p[0],g:p[1],b:p[2],a:p.length>3?p[3]:1} }
  /* fotos: lê uma grade pequena de luminância da imagem para saber se o trecho sob o ponto é claro ou escuro */
  var grades=(window.WeakMap?new WeakMap():null);
  function gradeImg(img){
    var g=grades&&grades.get(img); if(g) return g;
    if(!img.complete||!img.naturalWidth) return null;
    try{
      var N=16, c=document.createElement('canvas'); c.width=N; c.height=N;
      var cx=c.getContext('2d',{willReadFrequently:true}); cx.drawImage(img,0,0,N,N);
      var d=cx.getImageData(0,0,N,N).data, L=[];
      for(var i=0;i<N*N;i++){ L.push(d[i*4+3]<50?null:lum(d[i*4],d[i*4+1],d[i*4+2])) }
      g={N:N,L:L}; if(grades) grades.set(img,g); return g;
    }catch(e){ return null }
  }
  function lumImg(img,x,y){
    var g=gradeImg(img); if(!g) return null;
    var r=img.getBoundingClientRect(); if(!r.width||!r.height) return null;
    var u=(x-r.left)/r.width, v=(y-r.top)/r.height; if(u<0||u>1||v<0||v>1) return null;
    var nw=img.naturalWidth, nh=img.naturalHeight, fit=getComputedStyle(img).objectFit;
    if(fit==='cover'&&nw&&nh){
      var sc=Math.max(r.width/nw,r.height/nh), vw=r.width/sc, vh=r.height/sc;     /* trecho da foto que aparece */
      u=((nw-vw)/2+u*vw)/nw; v=((nh-vh)/2+v*vh)/nh;
    }
    var ix=Math.min(g.N-1,Math.max(0,Math.floor(u*g.N))), iy=Math.min(g.N-1,Math.max(0,Math.floor(v*g.N)));
    return g.L[iy*g.N+ix];
  }
  /* luminância do que está pintado atrás de um ponto da tela */
  var FORMAS={path:1,circle:1,rect:1,ellipse:1,polygon:1,polyline:1,line:1,use:1};
  function visivel(e){ var o=1,n=e,i=0; while(n&&n!==document.body&&i<14){ o*=parseFloat(getComputedStyle(n).opacity); if(o<.35) return false; n=n.parentElement; i++ } return true }
  function zonaDe(e){ var z=e.closest&&e.closest('[data-tom-zona]'); return z?z.getAttribute('data-tom-zona'):null }
  function lumEm(x,y){
    /* topo do banner: a faixa de cor sobre o mosaico garante o fundo liso sob o cabeçalho */
    var cap=document.querySelector('#pg-servico:not([hidden]) .sv-capa');
    if(cap){
      var cr=cap.getBoundingClientRect(), sh=parseFloat(getComputedStyle(cap,'::before').height)||0;
      var inCap=x>=cr.left&&x<=cr.right&&y>=cr.top&&y<=cr.bottom, fr=(cr.bottom-y)/(cr.height||1);
      var lim=matchMedia('(max-width:900px)').matches?0.72:(cap.classList.contains('bn-borrao')?0:0.18);   /* parte baixa coberta pelo fundo liso do banner */
      if(inCap&&((sh&&y<=cr.top+sh)||(lim&&fr<=lim))){ var cc=lerCor(getComputedStyle(cap).backgroundColor); if(cc) return lum(cc.r,cc.g,cc.b) }
    }
    var els=document.elementsFromPoint(x,y);
    for(var i=0;i<els.length;i++){
      var e=els[i];
      if(t.contains(e)||(lona&&lona.contains(e))) continue;
      var tag=e.tagName; if(tag==='HTML'||tag==='BODY'||tag==='svg'||tag==='SVG') continue;
      var cs=getComputedStyle(e);
      if(tag==='CANVAS'||tag==='VIDEO'){ var zc=zonaDe(e); if(zc) return CLARO[zc]?0.9:0.02; continue }
      if(cs.position==='fixed'&&!e.classList.contains('qs-inunda')) continue;
      if(!visivel(e)) continue;
      if(tag==='IMG'){
        var bm=e.closest&&e.closest('.sv-capa.bn-borrao .sv-mosaico');      /* mosaico esmaecido do banner de Saúde: vale a cor do banner */
        if(bm){ var cp=bm.closest('.sv-capa'), cb=lerCor(getComputedStyle(cp).backgroundColor); if(cb) return lum(cb.r,cb.g,cb.b) }
        var li=lumImg(e,x,y); if(li!=null) return li; continue }
      if(FORMAS[tag]){
        /* só formas grandes contam; traços finos e detalhes de adesivo não decidem o fundo */
        var f=cs.fill!=='none'?lerCor(cs.fill):null;
        if(f&&f.a*parseFloat(cs.fillOpacity||1)>=.6){ var fb=e.getBoundingClientRect(); if(Math.min(fb.width,fb.height)>=34) return lum(f.r,f.g,f.b) }
        var st=(cs.stroke!=='none'&&parseFloat(cs.strokeWidth)>=20)?lerCor(cs.stroke):null; if(st&&st.a>=.6) return lum(st.r,st.g,st.b);
        continue;
      }
      var c=lerCor(cs.backgroundColor);
      if(c&&c.a>=.6) return lum(c.r,c.g,c.b);
      if(cs.backgroundImage!=='none'){ var zi=zonaDe(e); if(zi) return CLARO[zi]?0.9:0.02 }
    }
    var b=lerCor(getComputedStyle(document.body).backgroundColor);
    return b?lum(b.r,b.g,b.b):0.9;
  }
  function media(el){
    var r=el.getBoundingClientRect(), y=r.top+r.height/2, xs=[r.left+r.width*.2,r.left+r.width*.5,r.left+r.width*.8], soma=0;
    xs.forEach(function(x){ soma+=lumEm(x,y) }); return soma/xs.length;
  }
  window.__tomMedir=function(){ return {l:media(t.querySelector('.marca .logo')),h:media(t.querySelector('.hamb'))} };
  function tom(){
    if(aberta) return;
    var logo=t.querySelector('.marca .logo'), nav=t.querySelector('nav'), hb=t.querySelector('.hamb');
    var tl,th,tn,root=document.documentElement;
    root.classList.add('tom-amostra');
    try{
      tl=media(logo)>CORTE?'claro':'escuro'; th=tl; tn=tl;
      if(hb&&hb.offsetParent!==null) th=media(hb)>CORTE?'claro':'escuro';
      if(nav&&nav.offsetParent!==null&&!t.classList.contains('compacto')) tn=media(nav)>CORTE?'claro':'escuro';
    }finally{ root.classList.remove('tom-amostra') }
    t.setAttribute('data-tl',tl); t.setAttribute('data-th',th); t.setAttribute('data-tn',tn);
    t.setAttribute('data-tom',tl);
  }
  function rola(){
    var y=Math.max(0,scrollY);
    t.classList.toggle('preso', y>40);
    var desceu = y>ultimo+4, subiu = y<ultimo-4;
    t.classList.toggle('compacto', y>40);
    if(desceu||subiu) ultimo=y;
    tom();
  }
  var tick=false;
  function ag(){ if(tick) return; tick=true; requestAnimationFrame(function(){rola();tick=false}) }
  addEventListener('scroll',ag,{passive:true}); addEventListener('resize',ag); addEventListener('hashchange',function(){ setTimeout(ag,120); setTimeout(ag,600) }); setInterval(ag,500); rola();

  /* menu mobile */
  function mexe(v){
    aberta=v; hamb.setAttribute('aria-expanded', v?'true':'false');
    lona.classList.toggle('aberta', v); document.body.classList.toggle('travado', v);
    if(v){ t.classList.remove('escondido'); ['data-tom','data-tl','data-th','data-tn'].forEach(function(a){ t.setAttribute(a,'escuro') }) } else tom();
  }
  if(hamb&&lona){
    hamb.addEventListener('click',function(){ mexe(!aberta) });
    lona.addEventListener('click',function(e){ if(e.target.closest('a')) mexe(false) });
    addEventListener('keydown',function(e){ if(e.key==='Escape'&&aberta) mexe(false) });
  }

  /* link ativo */
  var links=[].slice.call(t.querySelectorAll('nav>a[href^="#"]'));
  var alvos=links.map(function(a){return document.querySelector(a.getAttribute('href'))}).filter(Boolean);
  if(alvos.length && 'IntersectionObserver' in window){
    var vis={};
    var io=new IntersectionObserver(function(es){
      es.forEach(function(e){ vis[e.target.id]=e.isIntersecting });
      var atual=null;
      alvos.forEach(function(s){ if(vis[s.id]) atual=s.id });
      links.forEach(function(a){ a.setAttribute('aria-current', a.getAttribute('href')==='#'+atual ? 'true':'false') });
    },{rootMargin:'-45% 0px -45% 0px'});
    alvos.forEach(function(s){io.observe(s)});
  }
})();

/* ===== sobre: a frase acende letra a letra com a rolagem e os stickers colam ===== */
(function(){
  var sec=document.getElementById('sobre'); if(!sec) return;
  var ch=[].slice.call(sec.querySelectorAll('.acende .ch')), N=ch.length, W=8, ult=-1;
  var stk=[].slice.call(sec.querySelectorAll('.stk-i')).map(function(el){
    var cs=el.parentElement.querySelectorAll('.ch'); return {el:el, em:ch.indexOf(cs[cs.length-1])+1};
  });
  function aplica(p){
    var f=Math.round(p*(N+W)); if(f===ult) return; ult=f;
    for(var i=0;i<N;i++){ var c=i<f-W?'ch ok':(i<f?'ch fr':'ch'); if(ch[i].className!==c) ch[i].className=c }
    stk.forEach(function(o){ o.el.classList.toggle('on', f>=o.em) });
  }
  var reduz=matchMedia('(prefers-reduced-motion: reduce)').matches;
  var tp=sec.querySelector('.tampa path'), tr=sec.querySelector('.tampa rect'), serv=document.getElementById('servicos');
  function fecha(q){
    var e=q<.5?2*q*q:1-Math.pow(-2*q+2,2)/2;
    if(reduz){ tp.style.opacity=0; tr.style.opacity=q>.5?1:0 }
    else { tp.style.strokeDashoffset=(100-e*100).toFixed(2); tr.style.opacity=Math.max(0,Math.min(1,(q-.82)/.16)).toFixed(3) }
    var z=q>.35?'prof':'off'; if(sec.getAttribute('data-tom-zona')!==z){ sec.setAttribute('data-tom-zona', z); dispatchEvent(new Event('resize')) }
    var cheio=q>=1; sec.style.visibility=cheio?'hidden':''; if(serv) serv.classList.toggle('entrou', cheio);
  }
  function rola(){
    var palco=sec.parentElement, r=palco.getBoundingClientRect(), vh=innerHeight;
    var ini=Math.max(0, sec.offsetHeight-vh) - vh*0.12, total=Math.max(1,palco.offsetHeight-sec.offsetHeight), d=-r.top-ini;
    aplica(reduz?1:Math.max(0,Math.min(1,d/(total*0.5))));
    fecha(Math.max(0,Math.min(1,(d-total*0.6)/(total*0.4+vh*0.1))));
  }
  var tick=false;
  function ag(){ if(tick) return; tick=true; requestAnimationFrame(function(){rola();tick=false}) }
  addEventListener('scroll',ag,{passive:true}); addEventListener('resize',ag); rola();
})();

/* ===== seções que entram de lado: a anterior fica parada e a nova chega pela direita ===== */
(function(){
  var ls=[].slice.call(document.querySelectorAll('.sec[data-lado]')); if(!ls.length) return;
  if(matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  function pinta(){
    var vh=innerHeight;
    ls.forEach(function(s){
      var r=s.parentElement.getBoundingClientRect().top;
      if(r>=vh){ s.style.transform='translate3d(100%,0,0)'; s.style.clipPath='' }
      else if(r>0){
        var p=1-r/vh, raio=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--raio'))||46;
        var R=(raio*Math.min(1,(1-p)/.1)).toFixed(1), base=Math.max(0,s.offsetHeight-vh);
        s.style.transform='translate3d('+((1-p)*100).toFixed(2)+'%,'+(-r).toFixed(1)+'px,0)';
        /* recorta a seção na altura da tela, com os dois cantos da esquerda arredondados */
        s.style.clipPath='inset(0px 0px '+base+'px 0px round '+R+'px 0px 0px '+R+'px)';
      }
      else { s.style.transform=''; s.style.clipPath='' }
    });
  }
  (window.__aoRolar=window.__aoRolar||[]).push(pinta); var tick=false;
  function ag(){ if(tick) return; tick=true; requestAnimationFrame(function(){pinta();tick=false}) }
  addEventListener('scroll',ag,{passive:true}); addEventListener('resize',ag); addEventListener('load',ag); pinta();
})();

/* ===== cantos que se fecham: toda seção arredondada chega com os cantos redondos e, ao encostar no topo, fica reta ===== */
(function(){
  var ss=[].slice.call(document.querySelectorAll('.sec')).map(function(s){
    return {s:s, r:parseFloat(getComputedStyle(s).borderTopLeftRadius)||0};
  }).filter(function(o){return o.r>0});
  if(!ss.length) return;
  function pinta(){
    var vh=innerHeight;
    ss.forEach(function(o){
      var top=o.s.getBoundingClientRect().top, k=Math.max(0,Math.min(1,top/(vh*.14)));
      var r=(o.r*k).toFixed(1)+'px'; o.s.style.borderTopLeftRadius=r; o.s.style.borderTopRightRadius=r;
    });
  }
  var tick=false;
  function ag(){ if(tick) return; tick=true; requestAnimationFrame(function(){pinta();tick=false}) }
  addEventListener('scroll',ag,{passive:true}); addEventListener('resize',ag); pinta();
})();

/* ===== roteamento interno: Home / Todos os trabalhos / Case, sem novos arquivos ===== */
(function(){
  var home=document.getElementById('pg-home');
  var lista=document.getElementById('pg-trabalhos');
  var pc=document.getElementById('pg-case');
  var grade=document.getElementById('grade-completo');
  if(!home||!lista||!pc||!grade) return;
  function slug(t){return t.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
  var primeiros=[].slice.call(document.querySelectorAll('#grade .case'));
  var dados={},ordem=[],contador=0,paginaAtual='home',origemCase='trabalhos';

  function clona(card,visivel){
    var novo=card.cloneNode(true); contador++;
    if(visivel) novo.classList.add('on');
    // ID de SVG exclusivo: recorte de cor e segunda imagem seguem funcionando em todos os cards.
    [].slice.call(novo.querySelectorAll('clipPath[id]')).forEach(function(cp){
      var id=cp.id,prox=id+'-e'+contador; cp.id=prox;
      [].slice.call(novo.querySelectorAll('[style]')).forEach(function(el){
        var estilo=el.getAttribute('style');
        if(estilo.indexOf('#'+id+')')!==-1) el.setAttribute('style',estilo.split('#'+id+')').join('#'+prox+')'));
      });
    });
    if(visivel && window.iniciaCase) window.iniciaCase(novo);
    return novo;
  }

  // Os destaques da home tambem integram o portfolio; reutiliza as imagens inline sem duplicar os MB no arquivo.
  primeiros.slice().reverse().forEach(function(card){grade.insertBefore(clona(card,false),grade.firstChild)});
  var todos=[].slice.call(document.querySelectorAll('#grade .case, #grade-completo .case'));
  todos.forEach(function(c){
    var elNome=c.querySelector('.case-nome'),elServ=c.querySelector('.case-serv');
    if(!elNome||!elServ) return;
    var nome=elNome.textContent.trim(),serv=elServ.textContent.trim(),id=c.dataset.caseId||slug(nome);
    c.setAttribute('href','#case-'+id); c.dataset.caseId=id;
    if(!dados[id]) {dados[id]={nome:nome,serv:serv,card:c};ordem.push(id)}
  });
  var count=document.getElementById('portfolio-total');
  if(count)count.textContent=String(ordem.length).padStart(2,'0');

