  var CASES={}; try{CASES=JSON.parse(document.getElementById('cases-dados').textContent)}catch(e){}
  var modeloCapa=pc.querySelector('.capa').innerHTML, modeloGal=pc.querySelector('.galeria').innerHTML,
      modeloTxt=pc.querySelector('.txt').innerHTML;
  var ioCase=('IntersectionObserver' in window)?new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('on');ioCase.unobserve(e.target)}})},{threshold:.12}):null;
  /* símbolos da marca trocando de forma aleatória, junto com a cor de fundo */
  function trocaSimbolos(svg){
    var cores=JSON.parse(svg.getAttribute('data-troca')), sims=[].slice.call(svg.querySelectorAll('.fs-s')),
        bg=svg.querySelector('.fs-bg'), cor=svg.querySelector('.fs-cor'), s=0, c=0;
    function aplica(){ sims.forEach(function(x,i){x.classList.toggle('ativo',i===s)}); bg.setAttribute('fill',cores[c][0]); bg.style.fill=cores[c][0]; cor.style.color=cores[c][1] }
    function outro(n,atual){ var k; do{ k=Math.floor(Math.random()*n) }while(k===atual&&n>1); return k }
    s=outro(sims.length,-1); c=outro(cores.length,-1); aplica();
    if(matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    var t=setInterval(function(){
      if(!document.contains(svg)){ clearInterval(t); return }
      if(pc.hidden||document.hidden) return;
      s=outro(sims.length,s); c=outro(cores.length,c); aplica();
    },1500);
  }
  function midia(m,cls){
    var f=document.createElement('figure'); f.className='slot '+cls+' rv';
    var el;
    if(m.quad) f.classList.add('quad');
    if(m.svg){ f.classList.add('anim'); f.innerHTML=m.svg; var tr=f.querySelector('[data-troca]'); if(tr) trocaSimbolos(tr); if(ioCase) ioCase.observe(f); else f.classList.add('on'); return f; }
    if(m.video){ el=document.createElement('video'); el.src=m.video; el.autoplay=true; el.muted=true; el.loop=true; el.playsInline=true; el.setAttribute('playsinline',''); if(m.src) el.poster=m.src }
    else { el=document.createElement('img'); el.src=m.src; el.alt=m.alt||''; el.decoding='async' }
    if(m.pos) el.style.objectPosition=m.pos;
    f.appendChild(el); if(ioCase) ioCase.observe(f); else f.classList.add('on'); return f;
  }
  function conteudo(id){
    var c=CASES[id]||{};
    var capa=pc.querySelector('.capa'); capa.innerHTML=modeloCapa;
