  function vaiPara(id,suave){
    var t=id&&document.getElementById(id);
    if(!t || !home.contains(t)){window.scrollTo(0,0);dispatchEvent(new Event('scroll'));return}
    var pal=t.closest('.palco');
    var y=pal?pal.offsetTop+2:t.getBoundingClientRect().top+scrollY-(t.classList.contains('sec')?0:90);
    window.scrollTo({top:y,behavior:suave?'smooth':'auto'});dispatchEvent(new Event('scroll'));
  }

  function mostra(){
    var id='';try{id=decodeURIComponent(location.hash.slice(1))}catch(e){id=location.hash.slice(1)}
    var SERV=window.__SERV||(window.__SERV=JSON.parse(document.getElementById('servicos-dados').textContent));
    var nova=id.indexOf('case-')===0&&dados[id.slice(5)]?'case':id==='quem-somos'?'quem':id==='portfolio-completo'?'trabalhos':((id.indexOf('servico-')===0||id.indexOf('solucao-')===0)&&SERV[id.slice(8)])?'servico':'home';
    var mudou=nova!==paginaAtual;
    home.hidden=nova!=='home';lista.hidden=nova!=='trabalhos';pc.hidden=nova!=='case';document.getElementById('pg-servico').hidden=nova!=='servico';document.getElementById('pg-quem').hidden=nova!=='quem';
    document.body.dataset.pagina=nova;
    if(nova==='case'){
      preenche(id.slice(5));
      window.scrollTo(0,0);
    }else if(nova==='servico'){
      preencheServico(id.slice(8),SERV[id.slice(8)]);
      window.scrollTo(0,0);
    }else if(nova==='quem'){
      document.title='Quem somos · EmContent';
      window.scrollTo({top:0,left:0,behavior:'instant'});
      window.__qsInit&&window.__qsInit();
    }else if(nova==='trabalhos'){
      document.title='Trabalhos · EmContent';
      if(mudou)window.scrollTo(0,0);
    }else{
      document.title='EmContent · Criatividade aplicada';
      if(mudou)window.scrollTo(0,0);
      requestAnimationFrame(function(){dispatchEvent(new Event('resize'));vaiPara(id,false)});
    }
    paginaAtual=nova;
    if(nova==='servico'&&window.__svAnim) window.__svAnim();
    dispatchEvent(new Event('scroll'));
  }
  document.addEventListener('click',function(e){
    var a=e.target.closest&&e.target.closest('a[href^="#"]');if(!a)return;
    var id=a.getAttribute('href').slice(1);if(!id)return;
    if(id.indexOf('case-')===0){
      if(paginaAtual!=='case')origemCase=paginaAtual;
      return; // o hash abre o mesmo modelo de case, da home ou do portfólio
    }
    if(id==='portfolio-completo'){
      if(paginaAtual==='trabalhos'){e.preventDefault();window.scrollTo({top:0,behavior:'smooth'})}
      return;
    }
    var alvo=document.getElementById(id);
    if(!alvo||!home.contains(alvo))return;
    if(paginaAtual==='home'){
      e.preventDefault();history.pushState(null,'','#'+id);vaiPara(id,true);
    }
    // Em outra pagina, a mudança de hash volta para a home e faz o scroll certo.
