/* ===== revelar ao rolar ===== */
(function(){
  var els=[].slice.call(document.querySelectorAll('.rv'));
  if(!('IntersectionObserver' in window)){els.forEach(function(e){e.classList.add('on')});return}
  var io=new IntersectionObserver(function(es){es.forEach(function(e,i){if(e.isIntersecting){e.target.style.transitionDelay=(Math.min(i,4)*70)+'ms';e.target.classList.add('on');io.unobserve(e.target)}})},{rootMargin:'0px 0px -10% 0px'});
  els.forEach(function(e){io.observe(e)});
})();

/* ===== pincelada entre seções, puxada pela rolagem ===== */
(function(){
  if(matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var ps=[].slice.call(document.querySelectorAll('[data-pincel]'));
  if(!ps.length) return;
  var alvos=ps.map(function(s){return {p:s.querySelector('path'), sec:s.parentElement}});
  function pinta(){
    var vh=window.innerHeight;
    alvos.forEach(function(o){
      var r=o.sec.getBoundingClientRect();
      var t=(vh - r.bottom) / (vh*0.72);
      t=Math.max(0,Math.min(1,t));
      o.p.style.strokeDashoffset=(108 - t*108).toFixed(1);
    });
  }
  var tick=false;
  function ag(){ if(tick) return; tick=true; requestAnimationFrame(function(){pinta();tick=false}) }
  addEventListener('scroll',ag,{passive:true}); addEventListener('resize',ag); pinta();
})();

/* ===== cases: a cor do cliente escorre pelo card e revela a segunda imagem ===== */
(function(){
  var cs=[].slice.call(document.querySelectorAll('#grade .case, #grade-completo .case'));
  var reduz=matchMedia('(prefers-reduced-motion: reduce)').matches;
  function ease(x){ x=Math.max(0,Math.min(1,x)); return x<.5?4*x*x*x:1-Math.pow(-2*x+2,3)/2 }
  window.iniciaCase=function(c){
    var org=(c.dataset.org||'0 1').split(' ').map(Number);
    var pc=c.querySelector('.case-cor'), pb=c.querySelector('img.b');
    var cc=c.querySelector('clipPath[id^="cc"] path'), cb=c.querySelector('clipPath[id^="cb"] path');
    var t=0, alvo=0, rod=false, ant=0, DUR=1.05, S=2.3;
    function aplica(){
      var sc=S*ease(t/.72), sb=S*ease((t-.3)/.7), rot=(org[0]?-1:1)*38*t;
      cc.setAttribute('transform','translate('+org[0]+','+org[1]+') rotate('+rot.toFixed(1)+') scale('+sc.toFixed(4)+')');
      cb.setAttribute('transform','translate('+org[0]+','+org[1]+') rotate('+(-rot*.6).toFixed(1)+') scale('+sb.toFixed(4)+')');
      // força o navegador a redesenhar o recorte
      pc.style.transform='translateZ(0)'; pb.style.transform='translateZ(0)';
    }
    function quadro(ts){
      var dt=ant?(ts-ant)/1000:0; ant=ts;
      t+= (alvo>t?1:-1)*dt/DUR; if((alvo===1&&t>=1)||(alvo===0&&t<=0)){ t=alvo; aplica(); rod=false; ant=0; return }
      aplica(); requestAnimationFrame(quadro);
    }
    function vai(v){ alvo=v; if(reduz){ t=v; aplica(); return } if(!rod){ rod=true; requestAnimationFrame(quadro) } }
    c.addEventListener('pointerenter',function(){vai(1)}); c.addEventListener('pointerleave',function(){vai(0)});
    c.addEventListener('focus',function(){vai(1)}); c.addEventListener('blur',function(){vai(0)});
  };
  cs.forEach(window.iniciaCase);
})();

/* ===== filtros: serviço na home e no portfólio; área também no portfólio, combinados entre si ===== */
(function(){
  var reduz=matchMedia('(prefers-reduced-motion: reduce)').matches;
  [].slice.call(document.querySelectorAll('#trabalhos, #portfolio-completo')).forEach(function(sec){
    var sBtns=[].slice.call(sec.querySelectorAll('.filtros:not(.filtros-area) .filtro')), aBtns=[].slice.call(sec.querySelectorAll('.filtros-area .filtro[data-a]'));
    var cards=[].slice.call(sec.querySelectorAll('.cases .case')), est={s:sBtns[0]||null,a:'todas'};
    var ind=sec.querySelector('.portfolio-indicador'), vazio=sec.querySelector('.sem-case'), limpa=sec.querySelectorAll('.limpa-filtros');
    function okServ(c,b){ var f=b?b.dataset.f:'todos'; if(f==='todos') return true; var kw=(b.dataset.kw||f).split('|'), sv=(c.dataset.serv||'').toLowerCase(); return kw.some(function(w){ return sv.indexOf(w)>-1 }) }
    function okArea(c,a){ return a==='todas'||(c.dataset.areas||'').split(' ').indexOf(a)>-1 }
    function refiltra(animar){
      var n=0;
      cards.forEach(function(c){ var ok=okServ(c,est.s)&&okArea(c,est.a); var antes=c.style.display!=='none'; c.style.display=ok?'':'none';
        if(ok){ if(animar&&!reduz){ c.style.animation='none'; void c.offsetWidth; c.style.animation='awFiltro .6s cubic-bezier(.2,.7,.3,1) '+(Math.min(n,8)*45)+'ms backwards' } n++ } });
      sBtns.forEach(function(b){ var q=cards.filter(function(c){ return okServ(c,b)&&okArea(c,est.a) }).length; b.classList.toggle('vazio',!q&&b.dataset.f!=='todos'); b.setAttribute('aria-pressed',b===est.s?'true':'false') });
      aBtns.forEach(function(b){ var a=b.dataset.a, q=cards.filter(function(c){ return okServ(c,est.s)&&okArea(c,a) }).length; b.classList.toggle('vazio',!q&&a!=='todas'); b.setAttribute('aria-pressed',a===est.a?'true':'false') });
      var q=sec.querySelector('#portfolio-total'); if(q) q.textContent=String(n).padStart(2,'0');
      if(ind&&aBtns.length) ind.innerHTML='<span id="portfolio-total">'+String(n).padStart(2,'0')+'</span> '+(n===1?'projeto':'projetos')+' para explorar';
      var ativo=(est.s&&est.s.dataset.f!=='todos')||est.a!=='todas';
      [].forEach.call(limpa,function(l){ l.hidden=!ativo }); if(vazio) vazio.hidden=n>0;
    }
    function reset(){ est.s=sBtns[0]||null; est.a='todas'; refiltra(true) }
    sBtns.forEach(function(b){ b.addEventListener('click',function(){ est.s=b; refiltra(true) }) });
    aBtns.forEach(function(b){ b.addEventListener('click',function(){ est.a=(est.a===b.dataset.a&&b.dataset.a!=='todas')?'todas':b.dataset.a; refiltra(true) }) });
    [].forEach.call(limpa,function(l){ l.addEventListener('click',reset) });
    if(aBtns.length){ aBtns.forEach(function(b){ var a=b.dataset.a; if(a!=='todas'&&!cards.some(function(c){ return okArea(c,a) })) b.hidden=true }); refiltra(false) }
  });
})();

/* ===== sanfona de serviços ===== */
(function(){
  var sf=document.querySelector('.sanfona'); if(!sf) return;
  var ps=[].slice.call(sf.querySelectorAll('.painel'));
  var padrao=ps[0];
  function abre(p){ ps.forEach(function(x){ x.classList.toggle('on', x===p) }) }
  abre(padrao);
  /* cards fechados: o sticker encolhe o suficiente para nunca encostar no título vertical, mesmo em tela baixa */
  function cabeSticker(){ var col=getComputedStyle(sf).flexDirection==='column';
    ps.forEach(function(p){ var st=p.querySelector('.stk-c'), tb=p.querySelector('.tit-v b'); if(!st||!tb) return;
      if(col){ p.style.removeProperty('--stk-max'); return }
      var H=p.clientHeight; if(!H) return;
      var topo=Math.min(46,Math.max(30,innerWidth*.03)), base=Math.min(34,Math.max(22,innerWidth*.022)), ar=parseFloat(st.style.getPropertyValue('--ar'))||1;
      var livre=H-topo-base-tb.offsetHeight-22;
      p.style.setProperty('--stk-max',Math.max(48,livre*ar*.9).toFixed(1)+'px') }) }
  cabeSticker(); addEventListener('resize',cabeSticker); if(document.fonts&&document.fonts.ready) document.fonts.ready.then(cabeSticker);
  ps.forEach(function(p){
    p.addEventListener('pointerenter',function(){ abre(p) });
    p.addEventListener('focus',function(){ abre(p) });
  });
  sf.addEventListener('pointerleave',function(){ abre(padrao) });
})();

