/* ===== faixa: a fita fica parada e o texto corre pelo caminho ===== */
(function(){
  var svg=document.querySelector('.faixa-svg'); if(!svg) return;
  var tp=svg.querySelector('textPath'), arco=svg.querySelector('#arco'); if(!tp||!arco) return;
  var S='\u00a0\u00a0\u2022\u00a0\u00a0';
  var UNI=['REDES SOCIAIS','BRANDING','AUDIOVISUAL','SITES','TEMPLATES','IA','EVENTOS',''].join(S);
  var NS='http://www.w3.org/2000/svg', un=0, off=0, ant=0, vis=true, rod=false, V=72;
  var reduz=matchMedia('(prefers-reduced-motion: reduce)').matches;
  function mede(){
