  }
  function quadro(t){
    if(!vis||reduz){rod=false;ant=0;return}
    var dt=ant?Math.min(.1,(t-ant)/1000):0; ant=t;
    if(un){ off=(off+V*dt)%un; tp.setAttribute('startOffset',(-off).toFixed(2)) }
