  addEventListener('pointerover',function(e){ if(e.target.closest&&e.target.closest(alvo)) g.classList.add('ativo') });
  addEventListener('pointerout',function(e){ if(e.target.closest&&e.target.closest(alvo)) g.classList.remove('ativo') });
