    g.style.transform='translate('+gx+'px,'+gy+'px)';
    requestAnimationFrame(loop);
  })();
})();

/* ===== leads: UTMs + envio de todos os formulários para o n8n ===== */
window.EMC=(function(){
  var WEBHOOK='https://auto.emcomjunto.com.br/webhook/9f7080e9-9908-4761-9bad-13f1bd5e4778';
  var UTM=['utm_source','utm_medium','utm_campaign','utm_id','utm_term','utm_content'];
  /* lê as UTMs só da URL atual (também depois do #, se houver). Sem UTM na URL, os campos vão vazios: nenhum valor padrão ou guardado */
  function utms(){
    var q=new URLSearchParams(location.search), hi=location.hash.indexOf('?'), h=hi>-1?new URLSearchParams(location.hash.slice(hi+1)):null, t={};
    UTM.forEach(function(k){ t[k]=q.get(k)||(h&&h.get(k))||'' });
    return t;
  }
  function campo(f,n){ var i=f.querySelector('input[type=hidden][name="'+n+'"]'); if(!i){ i=document.createElement('input'); i.type='hidden'; i.name=n; f.appendChild(i) } return i }
  function preenche(f,extra){
    var u=utms(); UTM.forEach(function(k){ campo(f,k).value=u[k]||'' });
    campo(f,'page_url').value=location.href; campo(f,'referrer').value=document.referrer||'';
    campo(f,'pagina').value=document.title;
    if(extra) Object.keys(extra).forEach(function(k){ campo(f,k).value=extra[k]==null?'':extra[k] });
  }
  /* envia como formulário (x-www-form-urlencoded): não exige CORS e o n8n recebe cada campo em body */
  function enviar(f,extra){
    preenche(f,extra);
    var d=new FormData(f), p=new URLSearchParams(), vistos={};
    [].forEach.call(f.elements,function(el){ var n=el.name; if(!n||vistos[n]) return; vistos[n]=1;
      if(el.type==='checkbox'&&f.querySelectorAll('input[type=checkbox][name="'+n+'"]').length===1){ p.append(n,el.checked?'sim':'nao'); return }
      p.append(n,d.getAll(n).map(function(x){return String(x).trim()}).filter(Boolean).join(', ')) });
    p.append('data_envio',new Date().toISOString());
    return fetch(WEBHOOK,{method:'POST',mode:'no-cors',keepalive:true,body:p}).catch(function(err){
      if(navigator.sendBeacon&&navigator.sendBeacon(WEBHOOK,p)) return; throw err });
  }
  function iniciais(){ [].forEach.call(document.querySelectorAll('form'),function(f){ preenche(f) }) }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',iniciais); else iniciais();
  /* telefone no padrão E.164 para o RD Station: (11) 99999-8888 -> +5511999998888 */
  function e164(v){ v=String(v||'').trim(); var d=v.replace(/\D/g,''); if(!d) return '';
    if(v.charAt(0)==='+') return '+'+d; if((d.length===12||d.length===13)&&d.indexOf('55')===0) return '+'+d; if(d.length===10||d.length===11) return '+55'+d; return '' }
  function mascara(v){ if(/^\s*\+/.test(v)) return '+'+v.replace(/\D/g,'').slice(0,15);
    var d=v.replace(/\D/g,'').slice(0,11); if(d.length<=2) return d.length?'('+d:'';
    var meio=d.length>10?5:4; return '('+d.slice(0,2)+') '+d.slice(2,2+meio)+(d.length>2+meio?'-'+d.slice(2+meio):'') }
  function atualizaPhone(f){ var w=f.querySelector('[name=whatsapp]'); if(w) campo(f,'phone').value=e164(w.value) }
  document.addEventListener('input',function(e){ var el=e.target; if(el.name!=='whatsapp'||!el.form) return;
    var m=mascara(el.value); if(m!==el.value) el.value=m; atualizaPhone(el.form) });
  /* garante o phone preenchido antes de qualquer leitura do envio (o RD lê o formulário no submit) */
  document.addEventListener('submit',function(e){ if(e.target.querySelector) atualizaPhone(e.target) },true);
  /* com a validação nativa, campo inválido mostra a mensagem de erro dos formulários de serviço/solução */
  document.addEventListener('invalid',function(e){ var f=e.target.form, er=f&&f.querySelector('.svf-erro'); if(er) er.hidden=false },true);
  return {utms:utms,preenche:preenche,enviar:enviar,e164:e164};
})();

/* ===== formulário da home (#orcamento) ===== */
(function(){
