/* ===== botão do WhatsApp: abre o formulário, envia ao n8n e abre a conversa ===== */
(function(){
  var bt=document.querySelector('.zap'), dl=document.getElementById('zapf'); if(!bt||!dl) return;
  var f=dl.querySelector('form'), aviso=dl.querySelector('.zapf-aviso'), WA='https://wa.me/5511975049866';
  function pagAtual(){ var pg=document.getElementById('pg-servico'); return pg&&!pg.hidden&&pg.dataset.servico?pg.dataset.servico:document.title }
  function fecha(){ if(dl.open){ dl.close(); bt.setAttribute('aria-expanded','false') } }
  bt.setAttribute('aria-expanded','false');
  bt.addEventListener('click',function(e){ e.preventDefault();
    if(!dl.show){ window.open(WA,'_blank','noopener'); return }
    if(dl.open){ fecha(); return }
    aviso.textContent=''; dl.show(); bt.setAttribute('aria-expanded','true'); setTimeout(function(){ f.nome.focus({preventScroll:true}) },60) });
  dl.querySelector('.zapf-x').addEventListener('click',fecha);
  document.addEventListener('keydown',function(e){ if(e.key==='Escape'&&dl.open){ fecha(); bt.focus() } });
  document.addEventListener('pointerdown',function(e){ if(dl.open&&!dl.contains(e.target)&&!bt.contains(e.target)) fecha() });
  f.addEventListener('submit',function(e){ e.preventDefault();
    var nome=f.nome.value.trim(), zap=f.whatsapp.value.trim();
    if(!nome||!zap){ aviso.textContent='Falta o nome e o WhatsApp para a gente te responder.'; (nome?f.whatsapp:f.nome).focus(); return }
    var d=new FormData(f), v=function(k){return (d.get(k)||'').toString().trim()}, todas=d.getAll('servicos').join(', ');
    var linhas=['Olá, EmContent! Vim pelo site.','','*Nome:* '+v('nome'),v('empresa')?'*Marca:* '+v('empresa'):'','*WhatsApp:* '+v('whatsapp'),v('site')?'*Instagram/site:* '+v('site'):'',
      todas?'*O que preciso:* '+todas:'',v('mensagem')?'*Ideia:* '+v('mensagem'):''].filter(function(x){return x!==''});
    EMC.enviar(f,{pagina:pagAtual()}).catch(function(){});
    window.open(WA+'?text='+encodeURIComponent(linhas.join('\n')),'_blank','noopener');
    aviso.textContent='Prontinho, '+nome.split(' ')[0]+'! A conversa abriu no WhatsApp.';
    f.reset(); setTimeout(fecha,2200);
  });
})();
