<script>
/* soluções: coverflow infinito (clique no card do lado, arraste, pontos ou setas do teclado) */
(function(){
  var cf=document.querySelector('.cf'); if(!cf) return;
  var cs=[].slice.call(cf.querySelectorAll('.mk')), n=cs.length, at=0, ult={};
  var pts=cf.parentElement.querySelector('.cf-pontos');
  if(pts){ pts.setAttribute('aria-hidden','false'); pts.innerHTML=cs.map(function(c,i){return '<button type="button" aria-label="Mercado '+(i+1)+' de '+n+'"></button>'}).join('') }
  var bs=pts?[].slice.call(pts.children):[];
  function rel(i){ var d=((i-at)%n+n)%n; if(d>n/2) d-=n; return d }
  function pos(){
    var mob=innerWidth<=600, passo=mob?62:58, rot=mob?30:38;
    cs.forEach(function(c,i){ var d=rel(i), ad=Math.abs(d), antes=ult[i];
      if(antes!==undefined && Math.abs(antes-d)>2){ c.classList.add('salta'); requestAnimationFrame(function(){ requestAnimationFrame(function(){ c.classList.remove('salta') }) }) }
      ult[i]=d;
      c.style.transform='translateX('+(d*passo)+'%) translateZ('+(-ad*140)+'px) rotateY('+(d===0?0:(d>0?-rot:rot))+'deg) scale('+(d===0?1:.86)+')';
      c.style.zIndex=20-ad; c.style.filter=d===0?'none':'brightness(.84)'; c.style.opacity=ad>3?0:1;
      c.classList.toggle('centro',d===0); c.setAttribute('aria-hidden',d===0?'false':'true'); c.tabIndex=d===0?0:-1 });
    bs.forEach(function(b,i){ b.classList.toggle('on',i===at) });
  }
  function vai(k){ at=((k%n)+n)%n; pos() }
  cs.forEach(function(c,i){ c.addEventListener('click',function(e){ if(rel(i)!==0){ e.preventDefault(); e.stopImmediatePropagation(); vai(i) } },true) });
  bs.forEach(function(b,i){ b.addEventListener('click',function(){ vai(i) }) });
  cf.addEventListener('keydown',function(e){ if(e.key==='ArrowRight'){ vai(at+1); e.preventDefault() } if(e.key==='ArrowLeft'){ vai(at-1); e.preventDefault() } });
  var x0=null, moveu=false;
  cf.addEventListener('pointerdown',function(e){ x0=e.clientX; moveu=false });
  addEventListener('pointerup',function(e){ if(x0===null) return; var dx=e.clientX-x0; x0=null; if(Math.abs(dx)>40){ moveu=true; vai(at+(dx<0?1:-1)) } });
  cf.addEventListener('click',function(e){ if(moveu){ e.preventDefault(); e.stopImmediatePropagation(); moveu=false } },true);
  addEventListener('resize',pos); pos();
  /* gira sozinho; para quando o mouse (ou o foco) está sobre o carrossel */
  var parado=false, emVista=false, timer=null, reduzC=matchMedia('(prefers-reduced-motion: reduce)').matches, toque=0;
  function agendaAuto(){ clearInterval(timer); if(reduzC) return; timer=setInterval(function(){ if(!parado&&emVista&&!document.hidden&&Date.now()>toque) vai(at+1) },3000) }
  var _vai=vai; vai=function(k){ _vai(k); agendaAuto() };
  cf.addEventListener('pointerenter',function(e){ if(e.pointerType==='mouse') parado=true });
  cf.addEventListener('pointerleave',function(e){ if(e.pointerType==='mouse') parado=false });
  cf.addEventListener('focusin',function(){ parado=true }); cf.addEventListener('focusout',function(){ parado=false });
  cf.addEventListener('pointerdown',function(){ toque=Date.now()+7000 });
  if('IntersectionObserver' in window) new IntersectionObserver(function(es){ emVista=es[0].isIntersecting },{threshold:.35}).observe(cf); else emVista=true;
  agendaAuto();
})();
</script>
