      for(var i=0;i<ws.length;i++) ws[i].classList.toggle('on',i<n) }
    var its=pg.querySelectorAll('.sv-cap-i'), at=0; for(var j=0;j<its.length;j++){ if(its[j].getBoundingClientRect().top<innerHeight*.55) at=j }
