    if(its.length&&num&&num.textContent!==String(at+1).padStart(2,'0')){ num.textContent=String(at+1).padStart(2,'0'); nome.textContent=(its[at].querySelector('.sv-cap-mini').textContent||'').replace(/^\d+ · /,'');
      [].slice.call(pg.querySelectorAll('.sv-cap-pts i')).forEach(function(x,k){x.classList.toggle('on',k===at)}); [].slice.call(its).forEach(function(x,k){x.classList.toggle('ativo',k===at)});
