    var man=pg.querySelector('.sv-man'); if(man&&!reduz){ var rr=man.getBoundingClientRect(), pr=(rr.top+rr.height/2-innerHeight/2)/innerHeight; [].slice.call(man.querySelectorAll('.sv-man-fl span')).forEach(function(e,k){ e.style.translate='0 '+(pr*[90,-120,140,-80][k]).toFixed(1)+'px' }) }
  }
