  function desenhaRisco(){
    if(!barra) return; var w=barra.offsetWidth, h=barra.offsetHeight; if(!w||!h) return;
    var svg=barra.querySelector('.sv-barra-risco'); svg.setAttribute('viewBox','0 0 '+w+' '+h);
