    base.slice().reverse().forEach(function(p){ d+=' L '+p[0].toFixed(1)+' '+p[1].toFixed(1) });
    d+=' C 8 '+(h*.96).toFixed(1)+' 0 '+(h*.78).toFixed(1)+' 16 '+(h*.52).toFixed(1)+' Z';
