      if(/audiovisual|foto/.test(p)){ k='camera'; fonte=q[2]&&q[2].querySelector('.stk-c svg') }
      else if(/web/.test(p)){ k='janela'; fonte=q[3]&&q[3].querySelector('.stk-c svg') }
      else if(/evento/.test(p)){ k='microfone'; fonte=q[4]&&q[4].querySelector('.stk-c svg') }
      else if(/social/.test(p)){ k='celular'; fonte=q[0]&&q[0].querySelector('.stk-c svg') }
