    function mola(e){ e.vx=(e.vx+(e.tx-e.x)*.14)*.74; e.x+=e.vx; e.vy=(e.vy+(e.ty-e.y)*.14)*.74; e.y+=e.vy; e.vr=(e.vr+(e.tr-e.r)*.14)*.74; e.r+=e.vr; e.vs=(e.vs+(e.ts-e.s)*.14)*.74; e.s+=e.vs; e.vax=(e.vax+(e.tax-e.ax)*.14)*.74; e.ax+=e.vax; e.vay=(e.vay+(e.tay-e.ay)*.14)*.74; e.ay+=e.vay }
    function quadro(){ var vivo=false;
