        var quieto=Math.abs(e.x-e.tx)+Math.abs(e.y-e.ty)+Math.abs(e.r-e.tr)+Math.abs(e.s-e.ts)*10+Math.abs(e.ax-e.tax)+Math.abs(e.ay-e.tay)<.03&&Math.abs(e.vx)+Math.abs(e.vy)+Math.abs(e.vr)+Math.abs(e.vs*10)+Math.abs(e.vax)+Math.abs(e.vay)<.02;
        if(quieto&&e.ts===1&&e.tx===0){ e.n.style.translate=e.n.style.rotate=e.n.style.scale=''; if(e.tilt) e.n.style.transform=''; vivos.delete(e) } else vivo=true });
