<script>
/* ===== cards de solução da home: imagens reais dos cases; o card em foco troca de imagem sozinho (as demais ficam paradas) ===== */
(function(){
  var reduz=matchMedia('(prefers-reduced-motion: reduce)').matches;
  var CARDS={
    'solucao-saude':[['cancer-de-pulmao','a','50% 38%'],['alzheimer','a','50% 0%'],['depressao','a','50% 50%'],['doenca-de-crohn','b','50% 50%']],
    'solucao-marcas-pessoais':[['dr-acioly','a','50% 72%'],['dra-mara-gandara','a','50% 72%'],['dr-acioly','b','50% 12%'],['dra-mara-gandara','b','50% 28%']],
    'solucao-food-service':[['dodoca','g0','50% 70%'],['dodoca','g4','50% 50%'],['dodoca','g3','50% 55%']]
  };
  var CASES=null;
  function src(id,t){
    if(t==='a'||t==='b'){ var i=document.querySelector('#grade-completo .case[data-case-id="'+id+'"] img.'+t); return i&&i.src }
    if(!CASES){ try{ CASES=JSON.parse(document.getElementById('cases-dados').textContent) }catch(e){ CASES={} } }
    var g=(CASES[id]&&CASES[id].galeria)||[], m=g[+t.slice(1)]; return m&&m.src&&!m.svg?m.src:null }
  Object.keys(CARDS).forEach(function(pag){
    var cta=document.querySelector('.cf a.mk-cta[data-pagina="'+pag+'"]'); if(!cta) return;
    var card=cta.closest('.mk'), box=card&&card.querySelector('.mk-img'); if(!box) return;
    var imgs=CARDS[pag].map(function(f){ var s=src(f[0],f[1]); if(!s) return null;
      var im=document.createElement('img'); im.className='mk-foto'; im.alt=''; im.decoding='async'; im.src=s; im.style.objectPosition=f[2]; box.appendChild(im); return im }).filter(Boolean);
    if(!imgs.length) return; imgs[0].classList.add('on'); card._f={imgs:imgs,i:0};
  });
  /* o carrossel já anda sozinho a cada 3 s, então a imagem muda quando o card sai do centro (na próxima vez ele volta com outra);
     com o mouse parado sobre o card central o carrossel pausa e a imagem passa a trocar devagar, para quem quiser ver mais */
  function avanca(c){ var f=c&&c._f; if(!f||f.imgs.length<2) return; f.imgs[f.i].classList.remove('on'); f.i=(f.i+1)%f.imgs.length; f.imgs[f.i].classList.add('on') }
  if(reduz) return;
  var cards=[].slice.call(document.querySelectorAll('.cf .mk')), tinha=new WeakMap();
  cards.forEach(function(c){ tinha.set(c,c.classList.contains('centro')) });
  var mo=new MutationObserver(function(ms){ ms.forEach(function(m){ var c=m.target, agora=c.classList.contains('centro'), antes=tinha.get(c); if(antes&&!agora) avanca(c); tinha.set(c,agora) }) });
  cards.forEach(function(c){ mo.observe(c,{attributes:true,attributeFilter:['class']}) });
  setInterval(function(){ if(document.hidden) return; var c=document.querySelector('.cf .mk.centro'); if(c&&c.matches(':hover')) avanca(c) },3200);
})();
</script>
<script>
/* Transição de página: cortina de cor com o nome. Nas páginas de serviço e solução, o EM do logo se desenha acima do nome. */
(function(){
  if(matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var EA='cubic-bezier(.7,0,.2,1)', busy=false, LIMA='#D4F75A', PROF='#031526';
  function dest(id){ if(id==='quem-somos') return {c:'#1A64F0',t:'#fff',n:'Quem somos'};
    var SV=window.__SERV||(window.__SERV=JSON.parse(document.getElementById('servicos-dados').textContent)), S=SV[id.slice(8)]; return S?{c:S.cor,t:S.txt,n:S.nome}:null }
  function esperar(ms){ return new Promise(function(r){ setTimeout(r,ms) }) }
  function quadro2(){ return new Promise(function(r){ requestAnimationFrame(function(){ requestAnimationFrame(r) }) }) }
  function anima(el,de,para,opt){ return el.animate([{strokeDashoffset:de},{strokeDashoffset:para}],Object.assign({easing:EA,fill:'both'},opt)).finished }
  var EM_D='M 12 84 C 40 78 68 58 62 38 C 56 18 22 24 22 54 C 22 84 52 96 78 82 C 88 76 94 62 95 46 L 95 88 L 95 46 C 96 24 132 22 133 46 L 133 88 L 133 46 C 134 22 170 22 171 46 L 171 80 C 171 94 182 97 192 90';
  function limpa(){ [].forEach.call(document.querySelectorAll('.tt-cur'),function(x){ x.remove() }); busy=false }
  async function transicao(d,href,e,a0){
    var r=a0.getBoundingClientRect(), x=e.clientX||r.left+r.width/2, y=e.clientY||r.top+r.height/2, far=Math.hypot(Math.max(x,innerWidth-x),Math.max(y,innerHeight-y))+40;
    var comEm=/^(servico|solucao)-/.test(href.slice(1));
    var claro=['#d4f75a','#c9b8ff','#9bd4f4'].indexOf((d.c||'').toLowerCase())>=0, traco=claro?PROF:LIMA;
    var cur=document.createElement('div'); cur.className='tt-cur'; cur.setAttribute('aria-hidden','true'); cur.style.background=d.c; cur.style.color=d.t;
    cur.innerHTML='<div class="tt-grp">'+(comEm?'<svg class="tt-em2" viewBox="4 18 196 84"><path pathLength="100" d="'+EM_D+'" stroke="'+traco+'" stroke-width="15"/></svg>':'')+'<span class="tt-n"></span></div>';
    cur.querySelector('.tt-n').textContent=d.n;
    cur.style.clipPath='circle(0px at '+x+'px '+y+'px)'; document.body.appendChild(cur); void cur.offsetWidth;
    cur.style.transition='clip-path .34s '+EA; cur.style.clipPath='circle('+far+'px at '+x+'px '+y+'px)';
    setTimeout(function(){ cur.classList.add('nome') },comEm?220:160);
    var p=null;
    if(comEm){ p=cur.querySelector('.tt-em2 path'); await anima(p,100,0,{duration:380,delay:80}); await esperar(80) } else { await esperar(400) }
    location.hash=href.slice(1); await quadro2();
    cur.classList.remove('nome'); if(p) anima(p,0,-100,{duration:300});
    cur.style.transition='clip-path .34s '+EA+' .04s'; cur.style.clipPath='circle(0px at '+x+'px '+y+'px)';
    await esperar(420); cur.remove(); busy=false }
  document.addEventListener('click',function(e){
    var a=e.target.closest&&e.target.closest('a[href^="#solucao-"],a[href^="#servico-"],a[href="#quem-somos"]'); if(!a) return;
    if(busy){ e.preventDefault(); return }
    if(e.defaultPrevented||e.button||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey) return;
    var href=a.getAttribute('href'); if(location.hash===href) return;
    var d=dest(href.slice(1)); if(!d) return;
    e.preventDefault(); busy=true;
